-- Monografkuratering av ketamin.
-- Faglig litteraturgjennomgang utført i vanlig ChatGPT 03.10.2026.
-- Migrasjonen stopper dersom målpanelene er endret etter preflight.

do $kuratering$
declare
  side uuid := intern.kuratering_start('ketamin');
  kilde constant text := 'Monografkuratering av ketamin 03.10.2026: oppsummering, virkninger, farmakodynamikk, dosering, farmakokinetikk og avhengighet';
  k record;
  ref uuid;
  kilder jsonb := '{}'::jsonb;
  oppdatering jsonb;
  referanser jsonb;
  data jsonb;
begin
  if side is null then
    return;
  end if;
  if intern.kuratering_utfort(kilde) then
    raise notice 'Kurateringen er alt gjort.';
    return;
  end if;

  perform intern.kuratering_antall(side, 'identitet', 'riktekst', 0);
  perform intern.kuratering_antall(side, 'virkninger', 'kinetikkort', 0);
  perform intern.kuratering_antall(side, 'farmakodynamikk', 'mekanismekort', 0);
  perform intern.kuratering_antall(side, 'dosering', 'riktekst', 0);
  perform intern.kuratering_antall(side, 'farmakokinetikk', 'kinetikkort', 0);
  perform intern.kuratering_antall(side, 'avhengighet_toleranse', 'kinetikkort', 0);

  create temporary table ketamin_kilder(
    nokkel text primary key, tittel text, forfattere text, aar text, lenke text
  ) on commit drop;
  insert into ketamin_kilder values
    ('spc_ketamin','Ketamin Abcur – preparatomtale (SPC)','Direktoratet for medisinske produkter','2026','https://produktinformasjon.legemiddelsok.no/preparatomtaler/14-10368.pdf'),
    ('spc_ketanest','Ketanest – preparatomtale (SPC)','Direktoratet for medisinske produkter','2021','https://preparatomtaler.blob.core.windows.net/spc/13-9423.pdf'),
    ('ema_spravato','Spravato – preparatomtale (EPAR Product Information)','European Medicines Agency','2025','https://www.ema.europa.eu/no/documents/product-information/spravato-epar-product-information_no.pdf'),
    ('dmp_trd','Intravenous ketamine for treatment-resistant depression: a health technology assessment','Ohm IK, Flatby AV, Stoinska-Schneider A, Hafstad E','2024','https://www.dmp.no/globalassets/documents/offentlig-finansiering-og-pris/metodevurderinger/medisinsk-utstyr/id2022-018_intravenous-ketamine-for-trd_offentlig.pdf'),
    ('nye_trd','ID2022_018 Ketamin – behandlingsresistent depresjon','Nye metoder / Beslutningsforum for nye metoder','2025','https://www.nyemetoder.no/metoder/ketamin/'),
    ('nye_suicid','ID2025_034 Ketamin – akutt suicidfare','Nye metoder / Beslutningsforum for nye metoder','2026','https://www.nyemetoder.no/metoder/id2025_034/'),
    ('mcgirr','A systematic review and meta-analysis of randomized, double-blind, placebo-controlled trials of ketamine in the rapid treatment of major depressive episodes','McGirr A, Berlim MT, Bond DJ, Fleck MP, Yatham LN, Lam RW','2015','https://doi.org/10.1017/S0033291714001603'),
    ('abbar','Ketamine for the acute treatment of severe suicidal ideation: double blind, randomised placebo controlled trial','Abbar M, Demattei C, El-Hage W, et al.','2022','https://doi.org/10.1136/bmj-2021-067194'),
    ('krystal','Subanesthetic effects of the noncompetitive NMDA antagonist, ketamine, in humans. Psychotomimetic, perceptual, cognitive, and neuroendocrine responses','Krystal JH, Karper LP, Seibyl JP, et al.','1994','https://doi.org/10.1001/archpsyc.1994.03950030035004'),
    ('gilling','Potency, voltage-dependency, agonist concentration-dependency, blocking kinetics and partial untrapping of the uncompetitive NMDA channel blocker memantine at human NMDA (GluN1/GluN2A) receptors','Gilling KE, Jatzke C, Hechenberger M, Parsons CG','2009','https://doi.org/10.1016/j.neuropharm.2009.01.012'),
    ('zhang','Structural basis of ketamine action on human NMDA receptors','Zhang Y, et al.','2021','https://doi.org/10.1038/s41586-021-03769-9'),
    ('chen','HCN1 channel subunits are a molecular substrate for hypnotic actions of ketamine','Chen X, Shu S, Bayliss DA','2009','https://doi.org/10.1523/JNEUROSCI.3481-08.2009'),
    ('perez_ruixo','Population Pharmacokinetics of Esketamine Nasal Spray and its Metabolite Noresketamine in Healthy Subjects and Patients with Treatment-Resistant Depression','Perez-Ruixo C, Rossenu S, Zannikos P, et al.','2021','https://doi.org/10.1007/s40262-020-00953-4'),
    ('vasudeva','Evaluating the abuse liability of ketamine in the treatment of mood disorders: A systematic review','Vasudeva S, Lovell GFM, Wong S, et al.','2026','https://doi.org/10.1177/02698811261453814'),
    ('mosca','Treatment and management approaches for ketamine misuse: A systematic review of medical interventions','Mosca A, Chiappini S, Miuli A, et al.','2026','https://doi.org/10.1016/j.josat.2026.210061'),
    ('roberts','The Pharmacological Management of Ketamine Use Disorder: A Systematic Review','Roberts E, Sanderson E, Guerrini I','2024','https://doi.org/10.1097/ADM.0000000000001340');

  for k in select * from ketamin_kilder order by nokkel loop
    ref := intern.kuratering_referanse(
      jsonb_build_object('tittel',k.tittel,'forfattere',k.forfattere,'aar',k.aar,'lenke',k.lenke),
      kilde);
    kilder := kilder || jsonb_build_object(k.nokkel,ref::text);
  end loop;

  -- Kort oppsummering skrives som syntese av den samlede evidensgjennomgangen.
  data := $json${"dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ketamin er et dissosiativt anestetikum som brukes som racemat, mens S-enantiomeren esketamin også finnes som parenteralt anestetikum/analgetikum og som intranasalt antidepressivum."},{"type":"sitering","attrs":{"referanser":["__spc_ketamin__","__spc_ketanest__","__ema_spravato__"]}}]},{"type":"paragraph","content":[{"type":"text","text":"Ved anestesidoser gir ketamin rask anestesi og uttalt analgesi med relativt bevart spontanrespirasjon og luftveisreflekser, samtidig som blodtrykk og puls vanligvis øker forbigående."},{"type":"sitering","attrs":{"referanser":["__spc_ketamin__","__spc_ketanest__"]}}]},{"type":"paragraph","content":[{"type":"text","text":"Subanestetiske doser kan gi markert, men kortvarig dissosiasjon, perseptuelle endringer og kognitiv svekkelse; intravenøst racemisk ketamin og intranasalt esketamin kan samtidig gi en rask antidepressiv effekt."},{"type":"sitering","attrs":{"referanser":["__krystal__","__mcgirr__","__ema_spravato__"]}}]},{"type":"paragraph","content":[{"type":"text","text":"Langtidseffekten av intravenøst ketamin ved depresjon er mindre avklart enn den akutte effekten, og i Norge er bruk ved behandlingsresistent depresjon innført med krav om systematisk oppfølging."},{"type":"sitering","attrs":{"referanser":["__dmp_trd__","__nye_trd__"]}}]},{"type":"paragraph","content":[{"type":"text","text":"Addiksjonsrisikoen er tydeligst ved langvarig, høy eller ikke-medisinsk eksponering, mens klinisk overvåket behandling så langt har vist lite tegn til craving, doseeskalering eller misbruk; langtidsdata er likevel begrenset."},{"type":"sitering","attrs":{"referanser":["__vasudeva__","__mosca__"]}}]}]}}$json$::jsonb;
  data := replace(data::text, '__spc_ketamin__', kilder->>'spc_ketamin')::jsonb;
  data := replace(data::text, '__spc_ketanest__', kilder->>'spc_ketanest')::jsonb;
  data := replace(data::text, '__ema_spravato__', kilder->>'ema_spravato')::jsonb;
  data := replace(data::text, '__krystal__', kilder->>'krystal')::jsonb;
  data := replace(data::text, '__mcgirr__', kilder->>'mcgirr')::jsonb;
  data := replace(data::text, '__dmp_trd__', kilder->>'dmp_trd')::jsonb;
  data := replace(data::text, '__nye_trd__', kilder->>'nye_trd')::jsonb;
  data := replace(data::text, '__vasudeva__', kilder->>'vasudeva')::jsonb;
  data := replace(data::text, '__mosca__', kilder->>'mosca')::jsonb;
  perform intern.kuratering_nytt(side, jsonb_build_object(
    'panel','identitet','posisjon',0,'elementtype','riktekst',
    'data',data,
    'referanser',jsonb_build_array(kilder->>'spc_ketamin',kilder->>'spc_ketanest',kilder->>'ema_spravato',kilder->>'krystal',kilder->>'mcgirr',kilder->>'dmp_trd',kilder->>'nye_trd',kilder->>'vasudeva',kilder->>'mosca')),
    '{}'::jsonb, kilde);

  -- Virkninger, farmakodynamikk, farmakokinetikk og avhengighet.
  for oppdatering in select value from jsonb_array_elements($json$[{"panel":"virkninger","posisjon":0,"elementtype":"kinetikkort","nokkel":{"tittel":"Dissosiativ anestesi og analgesi"},"data":{"tittel":"Dissosiativ anestesi og analgesi","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ketamin gir doseavhengig dissosiativ anestesi med amnesi og uttalt analgesi. Etter racemisk ketamin 2 mg/kg intravenøst inntrer kirurgisk anestesi vanligvis innen omtrent 1 minutt og varer 5–15 minutter; etter 10 mg/kg intramuskulært inntrer effekten etter 3–5 minutter og varer 12–25 minutter."}]},{"type":"paragraph","content":[{"type":"text","text":"Muskeltonus og øvre luftveisreflekser er ofte relativt bevart, men dette utelukker ikke aspirasjons- eller respirasjonsrisiko."}]}]}},"refs":["spc_ketamin","spc_ketanest"]},{"panel":"virkninger","posisjon":1,"elementtype":"kinetikkort","nokkel":{"tittel":"Dissosiasjon, persepsjon og kognisjon"},"data":{"tittel":"Dissosiasjon, persepsjon og kognisjon","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ved subanestetisk eksponering kan ketamin raskt gi dissosiasjon, depersonalisasjon/derealisasjon, perseptuelle endringer og psykotomimetiske symptomer, samt forbigående svekkelse av oppmerksomhet og hukommelse. Effektene er doseavhengige og er direkte vist i randomiserte, placebokontrollerte forsøk hos friske mennesker."}]},{"type":"paragraph","content":[{"type":"text","text":"Ved intranasalt esketamin er dissosiasjon vanlig og vanligvis kortvarig; den kliniske overvåkningen etter dosering er derfor en del av behandlingsopplegget."}]}]}},"refs":["krystal","ema_spravato"]},{"panel":"virkninger","posisjon":2,"elementtype":"kinetikkort","nokkel":{"tittel":"Kardiovaskulære og respiratoriske virkninger"},"data":{"tittel":"Kardiovaskulære og respiratoriske virkninger","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ketamin øker vanligvis blodtrykk, puls og minuttvolum forbigående. For racemisk ketamin angir preparatomtalen en median blodtrykksøkning på omtrent 20–25 % over utgangsnivå, med tilbakegang mot utgangsnivå i løpet av omtrent 15 minutter etter injeksjon."}]},{"type":"paragraph","content":[{"type":"text","text":"Etter intranasalt esketamin topper blodtrykksøkningen seg typisk rundt 40 minutter etter dosering og varer vanligvis omtrent 1–2 timer."}]},{"type":"paragraph","content":[{"type":"text","text":"Spontanrespirasjon er ofte relativt bevart ved anestesi, og ketamin har bronkodilaterende egenskaper. Rask intravenøs administrasjon eller høy dose kan likevel gi forbigående respirasjonsdepresjon."}]}]}},"refs":["spc_ketamin","spc_ketanest","ema_spravato"]},{"panel":"virkninger","posisjon":3,"elementtype":"kinetikkort","nokkel":{"tittel":"Antidepressiv effekt"},"data":{"tittel":"Antidepressiv effekt","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Intravenøst racemisk ketamin kan redusere depressive symptomer i løpet av timer. En meta-analyse av tidlige dobbeltblinde randomiserte studier fant ved 24 timer respons-OR 9,10 (NNT 3), remisjons-OR 7,06 (NNT 5) og en standardisert forskjell i depresjonsskår på 0,90 i favør av ketamin. Studiene var små, og nyere norsk metodevurdering understreker at dokumentasjonen for flerdosebehandling og langtidseffekt er langt mer usikker enn den akutte effekten."}]},{"type":"paragraph","content":[{"type":"text","text":"Ved behandlingsresistent depresjon forbedret intranasalt esketamin sammen med peroralt antidepressivum MADRS-skår omtrent 3,5 poeng mer enn placebo-nesespray med antidepressivum i en sentral fireukers studie. I en tilbakefallsstudie fikk omtrent 27 % tilbakefall ved fortsatt esketamin mot 45 % etter overgang til placebo, blant pasienter som først hadde oppnådd stabil respons eller remisjon."}]}]}},"refs":["mcgirr","dmp_trd","ema_spravato"]},{"panel":"virkninger","posisjon":4,"elementtype":"kinetikkort","nokkel":{"tittel":"Akutte suicidale symptomer"},"data":{"tittel":"Akutte suicidale symptomer","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"I en randomisert studie av 156 innlagte voksne med alvorlig suicidalitet ga to infusjoner med racemisk ketamin 0,5 mg/kg over 40 minutter, med 24 timers mellomrom, full remisjon av suicidale tanker på dag 3 hos 63,0 % mot 31,6 % med placebo (OR 3,7; 95 % KI 1,9–7,3). Effekten var tydelig heterogen mellom diagnoser: svært stor i bipolargruppen, men ikke statistisk signifikant i undergruppen med unipolar depresjon."}]},{"type":"paragraph","content":[{"type":"text","text":"Reduksjon av suicidale tanker er ikke det samme som dokumentert reduksjon i selvmordsforsøk eller selvmord; i studien var antallet forsøk frem til uke 6 likt mellom gruppene. I Norge ble intravenøst ketamin i 2026 innført som behandlingsmulighet ved akutt suicidfare i sykehus/DPS, med samtidig understreking av usikkerhet om effektens varighet."}]}]}},"refs":["abbar","nye_suicid"]},{"panel":"farmakodynamikk","posisjon":0,"elementtype":"mekanismekort","nokkel":{"maal":"NMDA-reseptor"},"data":{"maal":"NMDA-reseptor","mekanisme":"bruksavhengig_blokkering","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ketamin blokkerer NMDA-reseptorens ionekanal direkte og på en spennings- og bruksavhengig måte. I humane GluN1/GluN2A-reseptorer var ketamin en fullt fanget åpen-kanalblokker med IC50 omkring 0,71 µM ved −70 mV; strukturelle studier av humane NMDA-reseptorer lokaliserer S-ketamin i kanalens sentrale vestibyle."}]},{"type":"paragraph","content":[{"type":"text","text":"Denne målvirkningen er godt dokumentert, men den raske antidepressive effekten kan ikke uten videre reduseres til graden av NMDA-kanalblokkade alene; den videre kausale mekanismen er fortsatt ufullstendig avklart."}]}]}},"refs":["gilling","zhang"]},{"panel":"farmakodynamikk","posisjon":1,"elementtype":"mekanismekort","nokkel":{"maal":"HCN1-kanaler"},"data":{"maal":"HCN1-kanaler","mekanisme":"ionekanalpavirkning","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ketamin hemmer HCN1-holdige hyperpolariseringsaktiverte kationkanaler ved konsentrasjoner som overlapper anestetisk eksponering. I knockoutmodeller er følsomheten for ketamins hypnotiske effekt redusert, noe som støtter at HCN1 kan bidra til anestesieffekten."}]},{"type":"paragraph","content":[{"type":"text","text":"Den funksjonelle og atferdsmessige evidensen er preklinisk; kortet dokumenterer derfor et mulig sekundært anestesimål, ikke en etablert forklaring på den analgetiske eller antidepressive effekten."}]}]}},"refs":["chen"]},{"panel":"farmakokinetikk","posisjon":0,"elementtype":"kinetikkort","nokkel":{"tittel":"Absorpsjon og biotilgjengelighet"},"data":{"tittel":"Absorpsjon og biotilgjengelighet","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Racemisk ketamin absorberes raskt intramuskulært; preparatomtalen angir biotilgjengelighet omkring 90 %. Intranasalt esketamin har betydelig, men lavere absolutt biotilgjengelighet: populasjons-PK ga omtrent 54 % etter 56 mg og 51 % etter 84 mg."}]},{"type":"paragraph","content":[{"type":"text","text":"Administrasjonsvei påvirker derfor både moderstoffeksponering og forholdet mellom ketamin/esketamin og aktive metabolitter; tall fra én formulering skal ikke overføres direkte til en annen."}]}]}},"refs":["spc_ketamin","perez_ruixo"]},{"panel":"farmakokinetikk","posisjon":1,"elementtype":"kinetikkort","nokkel":{"tittel":"Distribusjon"},"data":{"tittel":"Distribusjon","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ketamin distribueres raskt til høyt perfunderte vev. For racematet angis plasmaproteinbinding omkring 50 % og en distribusjonshalveringstid omkring 10–15 minutter."}]},{"type":"paragraph","content":[{"type":"text","text":"For esketamin er plasmaproteinbindingen omtrent 43–45 %, og intravenøs steady-state distribusjonsvolum er omkring 709 liter, forenlig med omfattende vevsdistribusjon."}]}]}},"refs":["spc_ketamin","ema_spravato"]},{"panel":"farmakokinetikk","posisjon":2,"elementtype":"kinetikkort","nokkel":{"tittel":"Metabolisme og aktive metabolitter"},"data":{"tittel":"Metabolisme og aktive metabolitter","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ketamin og esketamin N-demetyleres i leveren til norketamin. For racemisk ketamin angir preparatomtalen CYP3A4 som viktigste enzym i humane levermikrosomer, med bidrag fra CYP2B6 og CYP2C9. For intranasalt esketamin angir preparatomtalen CYP2B6 og CYP3A4 som hovedenzymer, med mindre bidrag fra blant annet CYP2C19 og CYP2C9."}]},{"type":"paragraph","content":[{"type":"text","text":"Norketamin er farmakologisk aktivt, men mindre potent enn moderstoffet; videre CYP-avhengig metabolisme danner blant annet hydroksylerte metabolitter og konjugater."}]}]}},"refs":["spc_ketamin","ema_spravato"]},{"panel":"farmakokinetikk","posisjon":3,"elementtype":"kinetikkort","nokkel":{"tittel":"Eliminasjon og halveringstid"},"data":{"tittel":"Eliminasjon og halveringstid","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Etter parenteralt racemisk ketamin er terminal halveringstid kort, men tallene avhenger av studie og administrasjonsregime: Ketamin Abcur oppgir omkring 80 minutter, mens Ketanest oppgir omtrent 79–186 minutter for esketamin."}]},{"type":"paragraph","content":[{"type":"text","text":"Etter intranasalt esketamin er den terminale halveringstiden lengre, vanligvis 7–12 timer. Utskillelsen skjer hovedsakelig renalt som metabolitter; mindre enn 1 % av radiomerket esketamindose gjenfinnes uendret i urin."}]}]}},"refs":["spc_ketamin","spc_ketanest","ema_spravato"]},{"panel":"avhengighet_toleranse","posisjon":0,"elementtype":"kinetikkort","nokkel":{"tittel":"Toleranseutvikling"},"data":{"tittel":"Toleranseutvikling","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Toleranse og doseeskalering er beskrevet særlig ved hyppig, høy og ikke-medisinsk eksponering. Preparatomtalene advarer om at toleranse kan utvikles, spesielt hos personer med tidligere problematisk rusmiddelbruk."}]},{"type":"paragraph","content":[{"type":"text","text":"Dette skal ikke overføres direkte til overvåket antidepressiv behandling: en systematisk oversikt fra 2026 fant gjennomgående lite tegn til doseeskalering eller andre toleransesignaler i kontrollerte kliniske forløp, men langtidsdata og systematisk måling av slike utfall er fortsatt begrenset."}]}]}},"refs":["spc_ketamin","spc_ketanest","vasudeva"]},{"panel":"avhengighet_toleranse","posisjon":1,"elementtype":"kinetikkort","nokkel":{"tittel":"Abstinens, seponeringssyndrom og rebound-effekter"},"data":{"tittel":"Abstinens, seponeringssyndrom og rebound-effekter","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Abstinenssymptomer er rapportert ved ketaminbrukslidelse etter langvarig og omfattende bruk, men syndromets forekomst, typiske forløp og fysiologiske kjennetegn er dårlig karakterisert. En systematisk oversikt over farmakologisk behandling av ketaminbrukslidelse fant seks publikasjoner om abstinens, hovedsakelig kasuistikker og små serier; samlet evidenskvalitet var svært lav."}]},{"type":"paragraph","content":[{"type":"text","text":"Det finnes ikke tilsvarende dokumentasjon for et forutsigbart abstinens- eller rebound-syndrom etter kortvarig, klinisk overvåket antidepressiv behandling. Symptomtilbakekomst etter avsluttet antidepressiv effekt skal derfor ikke i seg selv omtales som rebound eller fysiologisk abstinens."}]}]}},"refs":["roberts","vasudeva"]},{"panel":"avhengighet_toleranse","posisjon":2,"elementtype":"kinetikkort","nokkel":{"tittel":"Addiksjon"},"data":{"tittel":"Addiksjon","dokument":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Langvarig ikke-medisinsk bruk kan utvikle seg til ketaminbrukslidelse med craving, kontrolltap, vedvarende bruk til tross for skade og høy tilbakefallsrisiko. Kliniske serier av behandlingssøkende personer viser samtidig betydelige somatiske komplikasjoner, særlig urinveis- og gastrointestinal toksisitet."}]},{"type":"paragraph","content":[{"type":"text","text":"Risikoen er tydelig kontekstavhengig. En systematisk oversikt fra 2026 av ketamin/esketamin ved stemningslidelser fant lite tegn til craving, doseeskalering, misbruk eller illegal bruk når behandlingen ble gitt i strukturerte, overvåkede kliniske settinger. Dette taler for lavere addiksjonsrisiko under slik administrasjon, men utelukker ikke risiko ved langvarig behandling eller hos sårbare pasienter."}]}]}},"refs":["mosca","vasudeva"]}]$json$::jsonb) loop
    select coalesce(jsonb_agg(to_jsonb(kilder->>x.nokkel) order by x.i),'[]'::jsonb)
      into referanser
      from jsonb_array_elements_text(oppdatering->'refs') with ordinality x(nokkel,i);

    perform intern.kuratering_nytt(side, jsonb_build_object(
      'panel',oppdatering->>'panel',
      'posisjon',(oppdatering->>'posisjon')::integer,
      'elementtype',oppdatering->>'elementtype',
      'data',oppdatering->'data',
      'referanser',referanser),
      oppdatering->'nokkel', kilde);
  end loop;

  -- Dosering med inline-siteringer fordi formuleringer og indikasjoner har ulike kilder.
  data := $json${"dokument":{"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Racemisk ketamin – anestesi"}]},{"type":"paragraph","content":[{"type":"text","text":"Godkjent anestesidosering: intravenøs induksjon vanligvis 2 mg/kg (omtrent 1–4,5 mg/kg) eller intramuskulært 10 mg/kg (omtrent 6,5–13,5 mg/kg). Vedlikehold kan gis som omtrent halv induksjonsdose ved behov eller som intravenøs infusjon; preparatomtalen angir 2–6 mg/kg/time ved vedlikehold. Dosen individualiseres etter respons og samtidig anestesi."},{"type":"sitering","attrs":{"referanser":["__spc_ketamin__"]}}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Esketamin injeksjon – anestesi og akutt analgesi"}]},{"type":"paragraph","content":[{"type":"text","text":"Ved generell anestesi brukes vanligvis 0,5–1 mg/kg intravenøst eller 2–4 mg/kg intramuskulært. Vedlikehold kan gis som omtrent halv induksjonsdose hvert 10.–15. minutt eller infusjon 0,5–3 mg/kg/time. Ved akuttmedisinsk analgesi angir preparatomtalen 0,125–0,25 mg/kg langsomt intravenøst eller 0,25–0,5 mg/kg intramuskulært."},{"type":"sitering","attrs":{"referanser":["__spc_ketanest__"]}}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Racemisk ketamin – behandlingsresistent depresjon (off-label)"}]},{"type":"paragraph","content":[{"type":"text","text":"Intravenøst racemisk ketamin brukes utenfor godkjent indikasjon. Det sentrale studiedesignet er omtrent 0,5 mg/kg over 40 minutter, mens den norske metodevurderingen inkluderte studier med 0,5–1 mg/kg og både enkelt- og flerdoseforløp. Norske myndigheter har innført behandlingen ved behandlingsresistent depresjon, men krever inntil videre systematisk oppfølging via register eller kliniske studier og anbefaler behandling i sykehus/DPS fordi langtidseffekten er usikker."},{"type":"sitering","attrs":{"referanser":["__mcgirr__","__dmp_trd__","__nye_trd__"]}}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Racemisk ketamin – akutt suicidfare (off-label)"}]},{"type":"paragraph","content":[{"type":"text","text":"En sentral randomisert studie brukte 0,5 mg/kg intravenøst over 40 minutter ved start og på nytt etter 24 timer. Dette er et evidensregime, ikke en universell nasjonal doseringsstandard. I Norge ble intravenøst ketamin i 2026 innført som behandlingsmulighet for voksne med akutt suicidfare i sykehus/DPS."},{"type":"sitering","attrs":{"referanser":["__abbar__","__nye_suicid__"]}}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Esketamin nesespray – behandlingsresistent depresjon"}]},{"type":"paragraph","content":[{"type":"text","text":"Voksne under 65 år: 56 mg på dag 1; deretter 56 eller 84 mg to ganger ukentlig i uke 1–4, én gang ukentlig i uke 5–8 og fra uke 9 én gang ukentlig eller annenhver uke etter effekt. Ved vedvarende nytte anbefales minst 6 måneders behandling etter bedring. Hos personer ≥65 år er startdosen 28 mg, med senere doser 28, 56 eller 84 mg etter effekt og toleranse. Administreres under direkte tilsyn."},{"type":"sitering","attrs":{"referanser":["__ema_spravato__"]}}]},{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"Esketamin nesespray – psykiatrisk nødsituasjon ved alvorlig depresjon"}]},{"type":"paragraph","content":[{"type":"text","text":"For voksne under 65 år er anbefalt dose 84 mg to ganger ukentlig i 4 uker, med reduksjon til 56 mg ved toleranseproblemer. Behandlingen gis sammen med peroralt antidepressivum og er ment som korttidsbehandling; den erstatter ikke behandling av den underliggende depressive episoden."},{"type":"sitering","attrs":{"referanser":["__ema_spravato__"]}}]}]}}$json$::jsonb;
  data := replace(data::text, '__spc_ketamin__', kilder->>'spc_ketamin')::jsonb;
  data := replace(data::text, '__spc_ketanest__', kilder->>'spc_ketanest')::jsonb;
  data := replace(data::text, '__mcgirr__', kilder->>'mcgirr')::jsonb;
  data := replace(data::text, '__dmp_trd__', kilder->>'dmp_trd')::jsonb;
  data := replace(data::text, '__nye_trd__', kilder->>'nye_trd')::jsonb;
  data := replace(data::text, '__abbar__', kilder->>'abbar')::jsonb;
  data := replace(data::text, '__nye_suicid__', kilder->>'nye_suicid')::jsonb;
  data := replace(data::text, '__ema_spravato__', kilder->>'ema_spravato')::jsonb;
  perform intern.kuratering_nytt(side, jsonb_build_object(
    'panel','dosering','posisjon',0,'elementtype','riktekst',
    'data',data,
    'referanser',jsonb_build_array(kilder->>'spc_ketamin',kilder->>'spc_ketanest',kilder->>'mcgirr',kilder->>'dmp_trd',kilder->>'nye_trd',kilder->>'abbar',kilder->>'nye_suicid',kilder->>'ema_spravato')),
    '{}'::jsonb, kilde);

  -- «Lært mestringsavhengighet» opprettes ikke: ketaminspesifikk evidens var utilstrekkelig.
end
$kuratering$;
